use std::io::{self, Read};

fn solve(mut jobs: Vec<[i32; 3]>) -> i32 {
    jobs.sort_by_key(|j| (j[1], j[0]));
    let mut chosen: Vec<[i32; 3]> = Vec::new();
    for job in jobs {
        let conflicts: i32 = chosen.iter()
            .filter(|old| old[0] < job[1] && job[0] < old[1])
            .map(|old| old[2]).sum();
        if job[2] > conflicts {
            chosen.retain(|old| old[1] <= job[0] || job[1] <= old[0]);
            chosen.push(job);
        }
    }
    chosen.iter().map(|job| job[2]).sum()
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut values = input.split_whitespace().map(|s| s.parse::<i32>().unwrap());
    let cases = values.next().unwrap();
    for _ in 0..cases {
        let n = values.next().unwrap();
        let jobs = (0..n).map(|_| [values.next().unwrap(), values.next().unwrap(), values.next().unwrap()]).collect();
        println!("{}", solve(jobs));
    }
}

import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Scanner;

public class Main {
    static int solve(List<int[]> jobs) {
        jobs.sort(Comparator.<int[]>comparingInt(j -> j[1]).thenComparingInt(j -> j[0]));
        List<int[]> chosen = new ArrayList<>();
        for (int[] job : jobs) {
            int conflicts = 0;
            for (int[] old : chosen) {
                if (old[0] < job[1] && job[0] < old[1]) conflicts += old[2];
            }
            if (job[2] > conflicts) {
                chosen.removeIf(old -> old[0] < job[1] && job[0] < old[1]);
                chosen.add(job);
            }
        }
        return chosen.stream().mapToInt(j -> j[2]).sum();
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int cases = scanner.nextInt();
        for (int c = 0; c < cases; c++) {
            int n = scanner.nextInt();
            List<int[]> jobs = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                jobs.add(new int[]{scanner.nextInt(), scanner.nextInt(), scanner.nextInt()});
            }
            System.out.println(solve(jobs));
        }
    }
}

import java.util.Scanner

fun solve(jobs: List<IntArray>): Int {
    val ordered = jobs.sortedWith(compareBy<IntArray> { it[1] }.thenBy { it[0] })
    val chosen = mutableListOf<IntArray>()
    for (job in ordered) {
        val conflicts = chosen.filter { it[0] < job[1] && job[0] < it[1] }.sumOf { it[2] }
        if (job[2] > conflicts) {
            chosen.removeAll { it[0] < job[1] && job[0] < it[1] }
            chosen.add(job)
        }
    }
    return chosen.sumOf { it[2] }
}

fun main() {
    val scanner = Scanner(System.`in`)
    repeat(scanner.nextInt()) {
        val jobs = List(scanner.nextInt()) {
            intArrayOf(scanner.nextInt(), scanner.nextInt(), scanner.nextInt())
        }
        println(solve(jobs))
    }
}

#include <algorithm>
#include <array>
#include <iostream>
#include <vector>
using Job = std::array<int, 3>;

int solve(std::vector<Job> jobs) {
    std::sort(jobs.begin(), jobs.end(), [](const Job& a, const Job& b) {
        return a[1] != b[1] ? a[1] < b[1] : a[0] < b[0];
    });
    std::vector<Job> chosen;
    for (const auto& job : jobs) {
        int conflicts = 0;
        for (const auto& old : chosen)
            if (old[0] < job[1] && job[0] < old[1]) conflicts += old[2];
        if (job[2] > conflicts) {
            chosen.erase(std::remove_if(chosen.begin(), chosen.end(), [&](const Job& old) {
                return old[0] < job[1] && job[0] < old[1];
            }), chosen.end());
            chosen.push_back(job);
        }
    }
    int result = 0;
    for (const auto& job : chosen) result += job[2];
    return result;
}

int main() {
    int cases;
    std::cin >> cases;
    while (cases--) {
        int n;
        std::cin >> n;
        std::vector<Job> jobs(n);
        for (auto& job : jobs) std::cin >> job[0] >> job[1] >> job[2];
        std::cout << solve(jobs) << '\n';
    }
}

